//! CozoDB relational-graph-vector database plugin.
//!
//! Schema derived from CozoDB official documentation (docs.cozodb.org/en/latest/).
//! CozoDB is a Datalog database with dynamic schema — relations are created with
//! `:create` specifying key/value columns and types. The system exposes metadata
//! via `::relations`, `::columns`, `::indices` system ops.
//!
//! Column types (from docs.cozodb.org/en/latest/datatypes.html):
//!   Atomic: Int, Float, Bool, String, Bytes, Uuid, Json, Validity
//!   Composite: [Type] (list), (T1, T2) (tuple), <F32; N> (vector)
//!   Special: Any, Any? (nullable)
//!
//! Engines: mem, sled, rocksdb, sqlite
//! Access levels: normal, protected, read_only, hidden

use super::plugin_schema_defs::schema_from_state;
use anyhow::Result;
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::PluginSchema;
use serde::{Deserialize, Serialize};
use simd_json::{json, OwnedValue as Value};

const DEFAULT_COZO_DB_PATH: &str = "/var/lib/opdbus/cognitive.db";

/// CozoDB column definition — mirrors `::columns` system op output.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CozoColumn {
    pub name: String,
    pub r#type: String,     // Int, Float, Bool, String, Bytes, Uuid, Json, Validity, Any, Any?
    pub is_key: bool,       // true if before => in :create spec
    pub default: Option<String>,
    pub description: String,
}

/// CozoDB index definition — mirrors `::indices` system op output.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CozoIndex {
    pub name: String,       // e.g. "relation_name:index_name"
    pub relation: String,
    pub columns: Vec<String>,
}

/// CozoDB trigger — mirrors `::show_triggers` system op output.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CozoTrigger {
    pub relation: String,
    pub event: String,      // "put", "rm", "replace"
    pub query: String,
}

/// CozoDB stored relation — mirrors `::relations` + `::columns` system op output.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CozoRelation {
    pub name: String,
    pub description: String,
    pub keys: Vec<CozoColumn>,
    pub values: Vec<CozoColumn>,
    pub access_level: String, // normal, protected, read_only, hidden
    pub row_count: Option<u64>,
}

/// CozoDB HNSW vector index — from docs.cozodb.org/en/latest/vector.html
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CozoHnswIndex {
    pub name: String,
    pub relation: String,
    pub vector_column: String,
    pub dim: u32,
    pub dtype: String,      // "f32" or "f64"
    pub m: u32,
    pub ef_construction: u32,
    pub ef_search: u32,
    pub distance: String,   // "Cosine", "Euclid", "Dot"
}

/// Top-level CozoDB plugin state — the shape the projection tree exposes.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CozoState {
    pub engine: String,         // mem, sled, rocksdb, sqlite
    pub path: String,           // database path (empty for mem)
    pub version: String,        // CozoDB version
    pub relations: Vec<CozoRelation>,
    pub indices: Vec<CozoIndex>,
    pub hnsw_indices: Vec<CozoHnswIndex>,
    pub triggers: Vec<CozoTrigger>,
    pub running_queries: u32,
}

pub struct CozoPlugin;

impl Default for CozoPlugin {
    fn default() -> Self {
        Self
    }
}

impl CozoPlugin {
    pub fn new() -> Self {
        Self
    }

    fn db_path() -> String {
        std::env::var("COGNITIVE_MCP_COZO_DB_PATH")
            .unwrap_or_else(|_| DEFAULT_COZO_DB_PATH.to_string())
    }

    fn engine() -> String {
        let path = Self::db_path();
        if path.is_empty() {
            "mem".to_string()
        } else {
            "sled".to_string()
        }
    }

    /// Exemplar state derived from CozoDB docs system ops structure.
    /// Field names and types match the `::relations`, `::columns`, `::indices`
    /// system op outputs and the datatypes reference.
    pub(crate) fn exemplar_state() -> CozoState {
        CozoState {
            engine: Self::engine(),
            path: Self::db_path(),
            version: "0.7.6".to_string(),
            relations: vec![CozoRelation {
                name: "example_relation".to_string(),
                description: String::new(),
                keys: vec![CozoColumn {
                    name: "id".to_string(),
                    r#type: "String".to_string(),
                    is_key: true,
                    default: None,
                    description: String::new(),
                }],
                values: vec![CozoColumn {
                    name: "data".to_string(),
                    r#type: "Json".to_string(),
                    is_key: false,
                    default: Some("'{}".to_string()),
                    description: String::new(),
                }],
                access_level: "normal".to_string(),
                row_count: Some(0),
            }],
            indices: vec![],
            hnsw_indices: vec![],
            triggers: vec![],
            running_queries: 0,
        }
    }
}

#[async_trait]
impl StatePlugin for CozoPlugin {
    fn name(&self) -> &str {
        "cozo"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    fn schema(&self) -> Option<PluginSchema> {
        let mut schema = cozo_schema();
        super::common::oscal::ensure_category_metadata_fields(&mut schema);
        Some(schema)
    }

    async fn calculate_diff(&self, _current: &Value, _desired: &Value) -> Result<StateDiff> {
        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions: vec![],
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: String::new(),
                desired_hash: String::new(),
            },
        })
    }

    async fn apply_state(&self, _diff: &StateDiff) -> Result<ApplyResult> {
        Ok(ApplyResult {
            success: true,
            changes_applied: vec![],
            errors: vec![],
            checkpoint: None,
        })
    }

    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
        Ok(true)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        Ok(Checkpoint {
            id: uuid::Uuid::new_v4().to_string(),
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: simd_json::json!(null),
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, _checkpoint: &Checkpoint) -> Result<()> {
        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: false,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }
}

pub(crate) fn cozo_schema() -> PluginSchema {
    let state =
        simd_json::serde::to_owned_value(CozoPlugin::exemplar_state()).unwrap_or_else(|_| json!({}));
    let mut schema = schema_from_state(
        "cozo",
        "data",
        "1.0.0",
        "CozoDB relational-graph-vector database — relations, indices, HNSW, triggers, Datalog",
        &state,
    );
    schema.subids.insert("__schema__".to_string(), "sch.software.plugin.cozo.schema@v1".to_string());
    schema.subids.insert("engine".to_string(), "src.software.plugin.cozo.engine@v1".to_string());
    schema.subids.insert("path".to_string(), "src.software.plugin.cozo.path@v1".to_string());
    schema.subids.insert("version".to_string(), "obs.software.plugin.cozo.version@v1".to_string());
    schema.subids.insert("relations".to_string(), "obs.software.plugin.cozo.relations@v1".to_string());
    schema.subids.insert("indices".to_string(), "obs.software.plugin.cozo.indices@v1".to_string());
    schema.subids.insert("hnsw_indices".to_string(), "obs.software.plugin.cozo.hnsw-indices@v1".to_string());
    schema.subids.insert("triggers".to_string(), "obs.software.plugin.cozo.triggers@v1".to_string());
    schema.subids.insert("running_queries".to_string(), "obs.software.plugin.cozo.running-queries@v1".to_string());
    schema
}

inventory::submit! {
    crate::default_registry::PluginReg::new("cozo", |_ctx| std::sync::Arc::new(CozoPlugin::new()))
}

//! Qdrant vector search engine plugin.
//!
//! Schema derived from Qdrant's official OpenAPI spec
//! (qdrant/qdrant/docs/redoc/master/openapi.json). Fields mirror the
//! `CollectionInfo`, `CollectionConfig`, `VectorParams`, `HnswConfig`,
//! `OptimizersConfig`, and `CollectionStatus` schemas defined there.

use super::plugin_schema_defs::schema_from_state;
use anyhow::Result;
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::PluginSchema;
use serde::{Deserialize, Serialize};
use simd_json::{json, OwnedValue as Value};

const DEFAULT_QDRANT_HTTP_ENDPOINT: &str = "http://127.0.0.1:6333";
const DEFAULT_QDRANT_GRPC_ENDPOINT: &str = "http://127.0.0.1:6334";

/// Qdrant collection info — mirrors `CollectionInfo` from the OpenAPI spec.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct QdrantCollectionInfo {
    pub name: String,
    pub status: String,         // CollectionStatus enum: green, yellow, grey, red
    pub optimizer_status: String, // OptimizersStatus enum: ok, disabled
    pub points_count: Option<u64>,
    pub indexed_vectors_count: Option<u64>,
    pub segments_count: u64,
    pub config: QdrantCollectionConfig,
    pub payload_schema: Value,
}

/// Mirrors `CollectionConfig` from the OpenAPI spec.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct QdrantCollectionConfig {
    pub params: QdrantCollectionParams,
    pub hnsw_config: QdrantHnswConfig,
    pub optimizer_config: QdrantOptimizersConfig,
    pub quantization_config: Option<String>, // scalar, product, binary, turbo, or null
    pub wal_config: Option<Value>,
    pub strict_mode_config: Option<Value>,
    pub metadata: Option<Value>,
}

/// Mirrors `CollectionParams` + `VectorsConfig` from the OpenAPI spec.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct QdrantCollectionParams {
    pub vectors: QdrantVectorParams,
    pub shard_number: Option<u32>,
    pub replication_factor: Option<u32>,
    pub write_consistency_factor: Option<u32>,
    pub read_fan_out_factor: Option<u32>,
    pub on_disk_payload: Option<bool>,
    pub sparse_vectors: Option<Value>,
}

/// Mirrors `VectorParams` from the OpenAPI spec.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct QdrantVectorParams {
    pub size: u64,
    pub distance: String, // Distance enum: Cosine, Euclid, Dot, Manhattan
    pub hnsw_config: Option<Value>,
    pub quantization_config: Option<String>,
    pub on_disk: Option<bool>,
    pub datatype: Option<String>, // Datatype enum: float32, uint8, float16, turbo4
    pub multivector_config: Option<Value>,
}

/// Mirrors `HnswConfig` from the OpenAPI spec.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct QdrantHnswConfig {
    pub m: u32,
    pub ef_construct: u32,
    pub full_scan_threshold: u32,
    pub max_indexing_threads: u32,
    pub on_disk: Option<bool>,
    pub payload_m: Option<u32>,
    pub m0: Option<u32>,
}

/// Mirrors `OptimizersConfig` from the OpenAPI spec.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct QdrantOptimizersConfig {
    pub deleted_threshold: f64,
    pub vacuum_min_vector_number: u64,
    pub default_segment_number: u32,
    pub max_segment_size: u64,
    pub flush_interval_sec: u64,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub indexing_threshold: Option<u64>,
}

/// Top-level Qdrant plugin state — the shape the projection tree exposes.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct QdrantState {
    pub version: String,
    pub title: String,
    pub commit: String,
    pub http_endpoint: String,
    pub grpc_endpoint: String,
    pub collections: Vec<QdrantCollectionInfo>,
    pub cluster_status: Option<Value>,
    pub telemetry: Option<Value>,
}

pub struct QdrantPlugin;

impl Default for QdrantPlugin {
    fn default() -> Self {
        Self
    }
}

impl QdrantPlugin {
    pub fn new() -> Self {
        Self
    }

    fn http_endpoint() -> String {
        std::env::var("QDRANT_HTTP_URL")
            .or_else(|_| std::env::var("COGNITIVE_MCP_QDRANT_URL"))
            .unwrap_or_else(|_| DEFAULT_QDRANT_HTTP_ENDPOINT.to_string())
    }

    fn grpc_endpoint() -> String {
        std::env::var("QDRANT_GRPC_URL")
            .unwrap_or_else(|_| DEFAULT_QDRANT_GRPC_ENDPOINT.to_string())
    }

    /// Exemplar state derived from Qdrant OpenAPI schema definitions.
    /// Field names, types, and enum values match the spec exactly.
    pub(crate) fn exemplar_state() -> QdrantState {
        QdrantState {
            version: "1.18.2".to_string(),
            title: "qdrant - vector search engine".to_string(),
            commit: String::new(),
            http_endpoint: Self::http_endpoint(),
            grpc_endpoint: Self::grpc_endpoint(),
            collections: vec![QdrantCollectionInfo {
                name: "example_collection".to_string(),
                status: "green".to_string(),
                optimizer_status: "ok".to_string(),
                points_count: Some(0),
                indexed_vectors_count: Some(0),
                segments_count: 0,
                config: QdrantCollectionConfig {
                    params: QdrantCollectionParams {
                        vectors: QdrantVectorParams {
                            size: 1024,
                            distance: "Cosine".to_string(),
                            hnsw_config: None,
                            quantization_config: None,
                            on_disk: Some(false),
                            datatype: Some("float32".to_string()),
                            multivector_config: None,
                        },
                        shard_number: Some(1),
                        replication_factor: Some(1),
                        write_consistency_factor: Some(1),
                        read_fan_out_factor: None,
                        on_disk_payload: Some(false),
                        sparse_vectors: None,
                    },
                    hnsw_config: QdrantHnswConfig {
                        m: 16,
                        ef_construct: 100,
                        full_scan_threshold: 10000,
                        max_indexing_threads: 0,
                        on_disk: Some(false),
                        payload_m: None,
                        m0: None,
                    },
                    optimizer_config: QdrantOptimizersConfig {
                        deleted_threshold: 0.2,
                        vacuum_min_vector_number: 1000,
                        default_segment_number: 0,
                        max_segment_size: 200_000,
                        flush_interval_sec: 10,
                        indexing_threshold: Some(20000),
                    },
                    quantization_config: None,
                    wal_config: None,
                    strict_mode_config: None,
                    metadata: None,
                },
                payload_schema: json!({}),
            }],
            cluster_status: None,
            telemetry: None,
        }
    }
}

#[async_trait]
impl StatePlugin for QdrantPlugin {
    fn name(&self) -> &str {
        "qdrant"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    fn schema(&self) -> Option<PluginSchema> {
        let mut schema = qdrant_schema();
        super::common::oscal::ensure_category_metadata_fields(&mut schema);
        Some(schema)
    }

    async fn calculate_diff(&self, _current: &Value, _desired: &Value) -> Result<StateDiff> {
        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions: vec![],
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: String::new(),
                desired_hash: String::new(),
            },
        })
    }

    async fn apply_state(&self, _diff: &StateDiff) -> Result<ApplyResult> {
        Ok(ApplyResult {
            success: true,
            changes_applied: vec![],
            errors: vec![],
            checkpoint: None,
        })
    }

    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
        Ok(true)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        Ok(Checkpoint {
            id: uuid::Uuid::new_v4().to_string(),
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: simd_json::json!(null),
