pub fn create_unix_socket(&self, name: impl Into<String>, ports: Vec<u16>) -> ApplyResult {
    // Provisioning is pure identity-tag registration: the shared
    // `container.sock` is owned by the tonic-web gRPC bridge, not this
    // plugin. We never `UnixListener::bind` here — that would race the
    // bridge for the socket. The authoritative state update (append/update
    // the `SocketEndpoint` keyed by `name`, idempotently) is performed by
    // `MutationEngine` when it routes the `createunixsocket` MethodCall.
    let name = name.into();
    ApplyResult {
        success: true,
        changes_applied: vec![format!(
            "registered '{}' on shared socket {} (ports {:?})",
            name, SHARED_CONTAINER_SOCKET, ports
        )],
        errors: vec![],
        checkpoint: None,
    }
}

