//! RocksDB engine plugin.
//!
//! Exposes the RocksDB engine backing CozoDB as a first-class D-Bus plugin:
//! its configuration baseline (mirroring `include/rocksdb/options.h`),
//! integrity/durability options, and runtime statistics. The plugin is a
//! schema/state-shape declaration only — it holds no RocksDB handle. Every
//! tuning change routes through the `mut.software.rocksdb.set-option@v1`
//! subid (an accountable CM-3/CM-6 enforcement point), and the integrity and
//! data-at-rest fields are declared as SI-7 / SC-28 observable subids.

use super::plugin_schema_defs::schema_from_state;
use anyhow::Result;
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::PluginSchema;
use serde::{Deserialize, Serialize};
use simd_json::{json, OwnedValue as Value};

/// RocksDB runtime statistics (read-only observation surface).
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RocksDbStats {
    pub block_cache_hit_ratio: f64,
    pub compaction_pending: bool,
    pub memtable_size: u64,
    pub live_sst_files_size: u64,
    pub stall_micros: u64,
}

/// Top-level RocksDB plugin state — the shape the projection tree exposes.
///
/// Field names mirror RocksDB `Options` (`include/rocksdb/options.h`) so the
/// schema-derived contract maps 1:1 to the engine's tunables.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RocksDbState {
    // Configuration baseline (CM-2 / CM-6).
    pub max_open_files: i64,
    pub write_buffer_size: u64,
    pub max_write_buffer_number: u32,
    pub compression: String,
    pub block_cache_size: u64,
    pub bloom_filter_bits_per_key: u32,
    pub level_compaction_dynamic_level_bytes: bool,
    pub block_size: u64,
    pub bytes_per_sync: u64,
    // Integrity / durability (SI-7).
    pub paranoid_checks: bool,
    pub block_protection_bytes_per_key: u32,
    pub verify_sst_unique_id_in_manifest: bool,
    // Runtime stats (read-only).
    pub stats: RocksDbStats,
}

pub struct RocksDbPlugin;

impl Default for RocksDbPlugin {
    fn default() -> Self {
        Self
    }
}

impl RocksDbPlugin {
    pub fn new() -> Self {
        Self
    }

    /// Exemplar state with RocksDB default-ish values for schema shape only.
    pub(crate) fn exemplar_state() -> RocksDbState {
        RocksDbState {
            max_open_files: -1,
            write_buffer_size: 67_108_864,
            max_write_buffer_number: 2,
            compression: "lz4".to_string(),
            block_cache_size: 8_388_608,
            bloom_filter_bits_per_key: 10,
            level_compaction_dynamic_level_bytes: true,
            block_size: 4_096,
            bytes_per_sync: 1_048_576,
            paranoid_checks: true,
            block_protection_bytes_per_key: 0,
            verify_sst_unique_id_in_manifest: true,
            stats: RocksDbStats {
                block_cache_hit_ratio: 0.0,
                compaction_pending: false,
                memtable_size: 0,
                live_sst_files_size: 0,
                stall_micros: 0,
            },
        }
    }
}

#[async_trait]
impl StatePlugin for RocksDbPlugin {
    fn name(&self) -> &str {
        "rocksdb"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    fn schema(&self) -> Option<PluginSchema> {
        let mut schema = rocksdb_schema();
        super::common::oscal::ensure_category_metadata_fields(&mut schema);
        Some(schema)
    }

    async fn calculate_diff(&self, _current: &Value, _desired: &Value) -> Result<StateDiff> {
        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions: vec![],
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: String::new(),
                desired_hash: String::new(),
            },
        })
    }

    async fn apply_state(&self, _diff: &StateDiff) -> Result<ApplyResult> {
        Ok(ApplyResult {
            success: true,
            changes_applied: vec![],
            errors: vec![],
            checkpoint: None,
        })
    }

    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
        Ok(true)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        Ok(Checkpoint {
            id: uuid::Uuid::new_v4().to_string(),
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: simd_json::json!(null),
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, _checkpoint: &Checkpoint) -> Result<()> {
        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: false,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }
}

pub(crate) fn rocksdb_schema() -> PluginSchema {
    let state = simd_json::serde::to_owned_value(RocksDbPlugin::exemplar_state())
        .unwrap_or_else(|_| json!({}));
    let mut schema = schema_from_state(
        "rocksdb",
        "data",
        "1.0.0",
        "RocksDB engine — config baseline, integrity/durability options, runtime stats",
        &state,
    );
    schema.subids.insert(
        "__schema__".to_string(),
        "sch.software.rocksdb.options@v1".to_string(),
    );
    schema.subids.insert(
        "paranoid_checks".to_string(),
        "obs.software.rocksdb.integrity-checks@v1".to_string(),
    );
    schema.subids.insert(
        "block_protection_bytes_per_key".to_string(),
        "obs.software.rocksdb.block-protection@v1".to_string(),
    );
    schema.subids.insert(
        "verify_sst_unique_id_in_manifest".to_string(),
        "obs.software.rocksdb.sst-verification@v1".to_string(),
    );
    schema.subids.insert(
        "compression".to_string(),
        "obs.software.rocksdb.compression@v1".to_string(),
    );
    schema.subids.insert(
        "stats".to_string(),
        "obs.software.rocksdb.stats@v1".to_string(),
    );
    // Accountable config-change enforcement point. `ensure_category_metadata_fields`
    // injects the required `actor_id` + `capability_id` fields for this mut.* subid.
    schema.subids.insert(
        "set_option".to_string(),
        "mut.software.rocksdb.set-option@v1".to_string(),
    );
    schema
}

inventory::submit! {
    crate::default_registry::PluginReg::new("rocksdb", |_ctx| std::sync::Arc::new(RocksDbPlugin::new()))
}

