/// Embed `text` as a document vector and upsert it into the reasoning-episode
/// collection with the supplied payload.
///
/// The point id is the SHA-256 of `text` rendered as a UUID, so re-embedding
/// identical content overwrites the same point (idempotent — no double-spend).
/// Reuses the existing `VoyageClient`; no new embedding HTTP path is added.
pub async fn embed_and_upsert(
    &self,
    text: &str,
    payload: serde_json::Map<String, Value>,
) -> Result<()> {
    use sha2::{Digest, Sha256};

    let vector = self
        .voyage_client
        .embed_document(text)
        .await
        .context("failed to embed document for subid-routed upsert")?;

    let digest = Sha256::digest(text.as_bytes());
    let mut id_bytes = [0u8; 16];
    id_bytes.copy_from_slice(&digest[..16]);
    let point_id = uuid::Uuid::from_bytes(id_bytes).to_string();

    let qdrant_payload: Payload = Value::Object(payload)
        .try_into()
        .context("failed to build qdrant payload from subid-routed metadata")?;

    let point = PointStruct::new(point_id, vector, qdrant_payload);

    self.client
        .upsert_points(UpsertPointsBuilder::new(
            self.collection_name.clone(),
            vec![point],
        ))
        .await
        .with_context(|| {
            format!(
                "failed to upsert subid-routed point into collection {}",
                self.collection_name
            )
        })?;

    Ok(())
}

