// Receiver for the subid router — taken before `mutation_engine` is moved
// into the server constructor.
let change_rx = mutation_engine.change_tx().subscribe();

let server = if let Some(provider) = plugin_provider {
    OperationGrpcServer::with_plugin_provider(mutation_engine, provider)
} else {
    OperationGrpcServer::new(mutation_engine)
};
let semantic_shuttle = match QdrantSemanticShuttle::new().await {
    Ok(shuttle) => Some(Arc::new(shuttle)),
    Err(error) => {
        warn!(%error, "semantic shuttle unavailable; SearchSemanticTrace will return failed_precondition");
        None
    }
};
let server = match &semantic_shuttle {
    Some(shuttle) => server.with_semantic_shuttle(shuttle.clone()),
    None => server,
};

// Spawn the Gemma subid router (FR-E1/E2): every MutationEngine StateChange is
// classified by subid, gated by Reggie O.P.A. (cozo `evaluate_mutation`),
// appended to the embedded cozo `audit_event` trail, and — for content-bearing
// obs/exp subids — embedded into Qdrant. Cozo is the in-process `op-cozo-store`
// graph store; qdrant is reused from the semantic shuttle above.
match op_cozo_store::CozoGraphShuttle::from_env() {
    Ok(cozo) => {
        let router = crate::subid_router::SubidRouter::new(
            change_rx,
            Arc::new(cozo),
            semantic_shuttle.clone(),
        );
        tokio::spawn(router.run());
    }
    Err(error) => {
        warn!(%error, "subid-router: embedded cozo unavailable; mutation audit/compliance projection disabled");
    }
}

